import { mkdirSync, writeFileSync, existsSync } from 'node:fs'
import { join } from 'node:path'
import {
  CURSOR_RULES_SNIPPET,
  AEON_SYSTEM_PROMPT,
  catalog,
  componentSchemas,
} from '@aeon-ui/schemas'

export type InitOptions = {
  cwd?: string
  force?: boolean
}

const STARTER = `/**
 * Aeon UI starter — generated by \`npx aeon-ui init\`
 * Headless: @aeon-ui/react · Styled: @aeon-ui/ui · Schemas: @aeon-ui/schemas
 */
import { Button, Field } from '@aeon-ui/ui'

export function AeonStarter() {
  return (
    <div>
      <Field.Root>
        <Field.Label>Email</Field.Label>
        <Field.Control type="email" placeholder="you@example.com" />
        <Field.Message />
      </Field.Root>
      <Button.Root status="idle">Continue</Button.Root>
    </div>
  )
}
`

export function initAeon(options: InitOptions = {}) {
  const cwd = options.cwd ?? process.cwd()
  const force = options.force ?? false
  const written: string[] = []

  const write = (rel: string, body: string) => {
    const path = join(cwd, rel)
    if (existsSync(path) && !force) {
      written.push(`skip ${rel} (exists)`)
      return
    }
    mkdirSync(join(path, '..'), { recursive: true })
    writeFileSync(path, body.endsWith('\n') ? body : `${body}\n`)
    written.push(`write ${rel}`)
  }

  write('.cursor/rules/aeon-ui.mdc', `---
description: Aeon UI — statechart-driven components for AI agents
globs: **/*.{tsx,ts,jsx,js}
alwaysApply: true
---

${CURSOR_RULES_SNIPPET.trim()}
`)

  write('aeon.cursorrules.md', `${CURSOR_RULES_SNIPPET.trim()}\n`)
  write('aeon.system-prompt.md', `${AEON_SYSTEM_PROMPT.trim()}\n`)
  write(
    'aeon.schemas/catalog.json',
    `${JSON.stringify(
      {
        $id: catalog.$id,
        title: catalog.title,
        description: catalog.description,
        version: catalog.version,
        principle: catalog.principle,
        attributes: catalog.attributes,
        components: catalog.components,
        note: 'Full schemas live under aeon.schemas/components/*.json',
      },
      null,
      2,
    )}\n`,
  )

  for (const [id, schema] of Object.entries(componentSchemas)) {
    write(`aeon.schemas/components/${id}.json`, `${JSON.stringify(schema, null, 2)}\n`)
  }

  write('src/components/AeonStarter.tsx', STARTER)

  write(
    'AEON_AI.md',
    `# Aeon UI — AI agent setup

Generated by \`npx aeon-ui init\`.

## Next steps

1. Install: \`npm install aeon-ui-engine react react-dom xstate @xstate/react\`
   - Postinstall links \`@aeon-ui/*\` into \`node_modules\` (re-run with \`npx aeon-ui link\` if needed).
2. CSS: \`import 'aeon-ui-engine/aeon.css'\` (e.g. root layout).
3. **Next.js:** add \`transpilePackages\` for \`@aeon-ui/ui\`, \`@aeon-ui/react\`, \`@aeon-ui/core\`, \`@aeon-ui/primitives\`, \`@aeon-ui/panda\`. Use \`"use client"\` for interactive components. No webpack aliases required.
4. **Vite (optional):** \`aeonUiVitePlugin()\` from \`aeon-ui-engine/vite\` still helps with optimizeDeps; scoped imports resolve via the link step alone.
5. Paste \`aeon.cursorrules.md\` into Cursor rules / system prompt (already mirrored to \`.cursor/rules/aeon-ui.mdc\`)
6. Constrain generation with JSON under \`aeon.schemas/\`

## Frameworks

Aeon is **React-first** (full catalog + styled layer). Next.js is supported. Vue / Solid / Svelte adapters exist but are thin — not the main product.

## Principle

**UI = f(state)** — never invent boolean combinations for states the schema does not list.
`,
  )

  return { cwd, written }
}
